def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v = v[:v.index('+')]

        # Split core version from pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        prerelease_identifiers = None
        if prerelease is not None:
            prerelease_identifiers = prerelease.split('.')

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_key(identifiers):
        if identifiers is None:
            # No pre-release sorts after pre-release
            return (1,)

        # Pre-release sorts before no pre-release
        keys = [0]
        for identifier in identifiers:
            if identifier.isdigit():
                # All-digit identifiers sort numerically, before non-digit
                keys.append((0, int(identifier)))
            else:
                # Non-digit identifiers sort by ASCII, after all-digit
                keys.append((1, identifier))
        return tuple(keys)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease = parse_version(version)
        return (major, minor, patch, prerelease_key(prerelease), index)

    # Enumerate to maintain stable sort
    indexed = list(enumerate(versions))
    indexed.sort(key=sort_key)

    return [version for _, version in indexed]

